37	function statusLabel(status: HealthAuthStatus): string {
38	    switch (status) {
39	        case 'granted':
40	            return 'Health access: granted'
41	        case 'denied':
42	            return 'Health access: denied'
43	        default:
44	            return 'Health access: not requested'
45	    }
46	}
