48	function dayLabel(date: Date): string {
49	    return `${WEEKDAYS[date.getDay()]} ${MONTHS[date.getMonth()]} ${date.getDate()}`
50	}
51	
52	function formatSteps(steps: number): string {
53	    return Math.round(steps).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',')
54	}
55	
56	function errorMessage(e: unknown): string {
57	    return e instanceof Error ? e.message : String(e)
58	}
59	
60	const authStatus = ref<HealthAuthStatus>('not-requested')
61	const statusText = ref(statusLabel('not-requested'))
62	const days = ref<{ key: number; text: string; isToday: boolean }[]>([])
63	
64	const accessGranted = computed(() => authStatus.value === 'granted')
65	
66	async function refreshDays() {
67	    try {
68	        const totals = await loadLast7Days()
69	        const todayKey = totals[0]?.date.getTime()
70	        days.value = totals.map(({ date, steps }) => {
71	            const isToday = date.getTime() === todayKey
72	            const text = `${dayLabel(date)} — ${formatSteps(steps)} steps${isToday ? ' (today)' : ''}`
73	            return { key: date.getTime(), text, isToday }
74	        })
75	    } catch (e) {
76	        statusText.value = errorMessage(e)
77	    }
78	}
79	
80	async function refreshStatus() {
81	    authStatus.value = getAuthStatus()
82	    statusText.value = statusLabel(authStatus.value)
83	    if (accessGranted.value) {
84	        await refreshDays()
85	    }
86	}
87	
88	async function onRequestAccess() {
89	    try {
90	        authStatus.value = await requestAuthorization()
91	        statusText.value = statusLabel(authStatus.value)
92	        if (accessGranted.value) {
93	            await refreshDays()
94	        }
95	    } catch (e) {
96	        statusText.value = errorMessage(e)
97	    }
98	}
99	
100	async function onLogSteps() {
101	    try {
102	        await logSteps(500)
103	        await refreshDays()
104	    } catch (e) {
105	        statusText.value = errorMessage(e)
106	    }
107	}
108	
109	function onNavigatedTo() {
110	    refreshStatus()
111	}
112	</script>
