1	import { knownFolders, path } from '@nativescript/core'
2	
3	export type SpeechAuthStatus = 'not-requested' | 'granted' | 'denied'
4	
5	let recognizer: SFSpeechRecognizer | null = null
6	
7	function getRecognizer(): SFSpeechRecognizer {
8	    if (!recognizer) {
9	        recognizer = SFSpeechRecognizer.new()
10	    }
11	    return recognizer
12	}
13	
14	function toError(error: NSError): Error {
15	    return new Error(error.localizedDescription)
16	}
17	
18	export function getAuthStatus(): SpeechAuthStatus {
19	    switch (SFSpeechRecognizer.authorizationStatus()) {
20	        case SFSpeechRecognizerAuthorizationStatus.Authorized:
21	            return 'granted'
22	        case SFSpeechRecognizerAuthorizationStatus.Denied:
23	        case SFSpeechRecognizerAuthorizationStatus.Restricted:
24	            return 'denied'
25	        default:
26	            return 'not-requested'
27	    }
28	}
29	
30	export function requestAuthorization(): Promise<SpeechAuthStatus> {
31	    return new Promise((resolve) => {
32	        SFSpeechRecognizer.requestAuthorization(() => {
33	            resolve(getAuthStatus())
34	        })
35	    })
36	}
37	
38	export function transcribeSample(onPartial: (text: string) => void): Promise<string> {
39	    return new Promise((resolve, reject) => {
40	        const filePath = path.join(knownFolders.currentApp().path, 'assets', 'sample.wav')
41	        const url = NSURL.fileURLWithPath(filePath)
42	        const request = new SFSpeechURLRecognitionRequest({ URL: url })
43	        request.shouldReportPartialResults = true
44	
45	        getRecognizer().recognitionTaskWithRequestResultHandler(request, (result, error) => {
46	            if (error) {
47	                reject(toError(error))
48	                return
49	            }
50	            if (!result) {
51	                return
52	            }
53	            const text = result.bestTranscription.formattedString
54	            if (result.final) {
55	                resolve(text)
56	            } else {
57	                onPartial(text)
58	            }
59	        })
60	    })
61	}
62

